import { Component, OnInit, inject, ChangeDetectorRef } from '@angular/core';
import { CommonModule, NgIf, NgFor, DatePipe } from '@angular/common';
import { AdminService } from '../../../core/services/admin.service';

@Component({
  selector: 'app-manage-applications',
  standalone: true,
  imports: [CommonModule, NgIf, NgFor, DatePipe],
  templateUrl: './manage-applications.component.html',
  styleUrls: ['./manage-applications.component.css']
})
export class ManageApplicationsComponent implements OnInit {
  private adminService = inject(AdminService);
  private cdr = inject(ChangeDetectorRef);

  applications: any[] = [];
  isLoading = false;
  selectedUser: any = null;
  showUserCard = false;

  ngOnInit(): void {
    this.loadApplications();
  }

  loadApplications(): void {
    this.isLoading = true;
    this.adminService.getAllApplications().subscribe({
      next: (data) => {
        this.applications = data;
        this.isLoading = false;
        this.cdr.detectChanges();
      },
      error: () => {
        this.isLoading = false;
      }
    });
  }

  onDeleteApplication(applicationId: number): void {
    if (!confirm('❌ Voulez-vous vraiment supprimer cette candidature ?')) {
      return;
    }

    this.adminService.deleteApplication(applicationId).subscribe({
      next: () => {
        this.applications = this.applications.filter(app => app.id !== applicationId);
        this.cdr.detectChanges();
      }
    });
  }

  openUserCard(user: any, role: string): void {
    this.selectedUser = { ...user, adminRole: role };
    this.showUserCard = true;
  }

  closeUserCard(): void {
    this.showUserCard = false;
    this.selectedUser = null;
  }

  getUserRoleLabel(user: any): string {
    return user?.adminRole === 'candidate' ? 'Candidat' : 'Recruteur';
  }
}
<div class="manage-container">
  <div class="card-header-flex">
    <div class="card-header-left">
      <h3><i class="bi bi-clipboard-data"></i> Gestion des Candidatures</h3>
      <p>Contrôlez les candidatures soumises et supprimez les entrées non conformes.</p>
    </div>
  </div>

  <div class="manage-card-premium">
    <div class="table-wrapper-premium">
      <div *ngIf="isLoading" class="loading-box">
        <i class="bi bi-arrow-clockwise spinning"></i> Chargement des candidatures...
      </div>

      <table *ngIf="!isLoading" class="jobs-table-premium">
        <thead>
          <tr>
            <th class="th-left-padding">Candidat / Offre</th>
            <th>Recruteur</th>
            <th>Statut</th>
            <th class="th-center-align">Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let app of applications" class="table-row-premium">
            <td class="job-company-cell">
              <span class="clickable-job-title clickable-user-name" (click)="openUserCard(app, 'candidate')">{{ app.candidate_name || app.name || 'Candidat inconnu' }}</span>
              <span class="company-sub-badge"><i class="bi bi-briefcase"></i> {{ app.job_title || 'Offre inconnue' }}</span>
            </td>
            <td class="date-text-cell-premium">
              <div class="date-container-premium">
                <i class="bi bi-building"></i>
                <span class="clickable-user-name" (click)="openUserCard(app, 'recruiter')">{{ app.recruiter_name || app.company_name || 'Recruteur inconnu' }}</span>
              </div>
            </td>
            <td>
              <span class="status-badge-fixed" [ngClass]="{
                'bg-emerald': app.status === 'Proposition' || app.status === 'Entretien',
                'bg-amber': app.status !== 'Proposition' && app.status !== 'Entretien'
              }">
                <span class="dot-status"></span>
                <span class="badge-text-span">{{ app.status || 'Nouveau' }}</span>
              </span>
            </td>
            <td class="status-cell-premium">
              <button class="btn-action-delete" (click)="onDeleteApplication(app.id)">
                <i class="bi bi-trash3-fill"></i> Supprimer
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>

  <div *ngIf="showUserCard && selectedUser" class="admin-user-card-overlay" (click)="closeUserCard()">
    <div class="admin-user-card" (click)="$event.stopPropagation()">
      <button class="admin-user-card-close" (click)="closeUserCard()">×</button>
      <div class="admin-user-card-header">
        <div>
          <h4>{{ selectedUser.adminRole === 'candidate' ? (selectedUser.candidate_name || 'Candidat') : (selectedUser.recruiter_name || selectedUser.company_name || 'Recruteur') }}</h4>
          <p class="admin-user-role">{{ getUserRoleLabel(selectedUser) }}</p>
        </div>
        <span class="admin-badge" [ngClass]="selectedUser.adminRole === 'candidate' ? (selectedUser.is_verified ? 'badge-success' : 'badge-warning') : (selectedUser.is_verified_company ? 'badge-success' : 'badge-warning')">
          {{ selectedUser.adminRole === 'candidate' ? (selectedUser.is_verified ? 'Compte vérifié' : 'Compte non vérifié') : (selectedUser.is_verified_company ? 'Entreprise certifiée' : 'Certification en attente') }}
        </span>
      </div>
      <div class="admin-user-card-body">
        <div class="admin-user-field"><span>Email</span><strong>{{ selectedUser.adminRole === 'candidate' ? selectedUser.candidate_email : selectedUser.recruiter_email }}</strong></div>
        <div class="admin-user-field"><span>Téléphone</span><strong>{{ selectedUser.adminRole === 'candidate' ? selectedUser.candidate_phone || '—' : selectedUser.recruiter_phone || '—' }}</strong></div>
        <div class="admin-user-field"><span>Adresse</span><strong>{{ selectedUser.adminRole === 'candidate' ? selectedUser.candidate_address || '—' : selectedUser.recruiter_address || '—' }}</strong></div>
        <div class="admin-user-field" *ngIf="selectedUser.adminRole === 'candidate'"><span>Offre concernée</span><strong>{{ selectedUser.job_title || '—' }}</strong></div>
        <div class="admin-user-field" *ngIf="selectedUser.adminRole === 'recruiter'"><span>Offre concernée</span><strong>{{ selectedUser.job_title || '—' }}</strong></div>
      </div>
    </div>
  </div>
</div>
